//! Replay the seeded random calculator corpus
//! (`oracle/random_calculator_tests.json`) through the host core.
//!
//! The corpus programs are generated by
//! `platform/scripts/gen_random_tests.py`; this file is the oracle author and
//! the regression gate:
//!
//! - `random_examples_replay` requires every example's asserted step suffixes
//!   and lamps to match the committed `expect` blocks. It re-derives them from
//!   the same core, so it guards the committed data against rot (and the core
//!   against regressions relative to the recorded expectations) — it is NOT
//!   independent evidence about the core itself. The core's independent
//!   anchors remain `manual_examples.rs` and `port_trace.rs`.
//! - `dump_random_oracle` (ignored) recomputes the `expect` blocks from the
//!   core and writes the merged document to `$RANDOM_ORACLE_OUT`. Expected
//!   output comes from this host implementation, never from the emulator
//!   under test (`system/busicom_141pf/emulator`), which shares no code with
//!   it; the emulator replays the same corpus against these expectations in
//!   `emulator/tests/random_replay.rs`.
//!
//! Regenerate with:
//! ```sh
//! py system/busicom_141pf/platform/scripts/gen_random_tests.py
//! RANDOM_ORACLE_OUT=system/busicom_141pf/firmware/oracle/random_calculator_tests.json \
//!   cargo +1.99.1 test --manifest-path system/busicom_141pf/firmware/Cargo.toml \
//!   --test random_calculator_tests dump_random_oracle -- --ignored
//! ```

use serde_json::{json, Map, Value};
use software::{Calculator, Key, Printer, Rounding, Row, Switches};
use std::path::Path;

#[derive(Clone, Debug, PartialEq)]
struct TapeRow {
    value: Option<String>,
    symbol: String,
    red: bool,
    rounded: bool,
}

#[derive(Default)]
struct Recorder(Vec<TapeRow>);

impl Printer for Recorder {
    fn print(&mut self, row: &Row) {
        let (value, symbol) = if row.overflow_line() {
            (None, "overflow".to_string())
        } else {
            let s: String = row.cols().iter().map(|&c| c as char).collect();
            let s = s.trim().to_string();
            (Some(s), row.oracle_symbol().to_string())
        };
        self.0.push(TapeRow {
            value,
            symbol,
            red: row.red(),
            rounded: row.rounded(),
        });
    }
}

fn expected_row(v: &Value) -> TapeRow {
    TapeRow {
        value: v["value"].as_str().map(str::to_string),
        symbol: v["symbol"].as_str().unwrap().to_string(),
        red: v["red"].as_bool().unwrap(),
        rounded: v["rounded"].as_bool().unwrap(),
    }
}

fn apply_switches(sw: &mut Switches, v: &Value) {
    if let Some(p) = v.get("precision") {
        sw.dp = p.as_u64().unwrap() as u8;
    }
    if let Some(r) = v.get("rounding") {
        sw.rounding = Rounding::from_selector(r.as_u64().unwrap() as u8).unwrap();
    }
}

fn key(codes: &Value, name: &Value) -> Key {
    let code = codes[name.as_str().unwrap()].as_u64().unwrap() as u8;
    Key::from_code(code).unwrap_or_else(|| panic!("no key for {code}"))
}

/// One step's replay outcome: rows printed during the step and the lamps at
/// its end.
struct StepRun {
    rows: Vec<TapeRow>,
    lamps: software::Lamps,
}

fn run_example(codes: &Value, ex: &Value) -> Vec<StepRun> {
    let mut sw = Switches {
        dp: 0,
        rounding: Rounding::Float,
    };
    apply_switches(&mut sw, &ex["switches"]);
    let mut calc = Calculator::new();
    let mut tape = Recorder::default();
    for k in ex["setup_keys"].as_array().unwrap() {
        calc.press(key(codes, k), sw, &mut tape);
    }
    let mut runs = Vec::new();
    for step in ex["steps"].as_array().unwrap() {
        let before = tape.0.len();
        if let Some(s) = step.get("switches") {
            apply_switches(&mut sw, s);
        }
        for k in step["keys"].as_array().map(Vec::as_slice).unwrap_or(&[]) {
            calc.press(key(codes, k), sw, &mut tape);
        }
        runs.push(StepRun {
            rows: tape.0[before..].to_vec(),
            lamps: calc.lamps(),
        });
    }
    runs
}

fn check_example(codes: &Value, ex: &Value) -> Vec<String> {
    let runs = run_example(codes, ex);
    let mut failures = Vec::new();
    for (i, (step, run)) in ex["steps"]
        .as_array()
        .unwrap()
        .iter()
        .zip(&runs)
        .enumerate()
    {
        let Some(expect) = step.get("expect") else {
            continue;
        };
        if let Some(rows) = expect.get("tape").and_then(Value::as_array) {
            let want: Vec<TapeRow> = rows.iter().map(expected_row).collect();
            if run.rows.len() < want.len() || run.rows[run.rows.len() - want.len()..] != want[..] {
                failures.push(format!(
                    "step {}: expected tape suffix {want:?}, got {:?}",
                    i + 1,
                    run.rows
                ));
            }
        }
        if let Some(lamps) = expect.get("lamps").and_then(Value::as_object) {
            for (name, v) in lamps {
                let got = match name.as_str() {
                    "memory" => run.lamps.memory,
                    "overflow" => run.lamps.overflow,
                    "negative" => run.lamps.negative,
                    other => panic!("unknown lamp {other}"),
                };
                if got != v.as_bool().unwrap() {
                    failures.push(format!(
                        "step {}: lamp {name} expected {v}, got {got}",
                        i + 1
                    ));
                }
            }
        }
    }
    failures
}

fn load_doc() -> Value {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(
        &std::fs::read_to_string(root.join("oracle/random_calculator_tests.json")).unwrap(),
    )
    .unwrap()
}

#[test]
fn random_examples_replay() {
    let doc = load_doc();
    assert_eq!(doc["schema_version"], 1);
    let examples = doc["examples"].as_array().unwrap();
    let mut failures = Vec::new();
    for ex in examples {
        let fails = check_example(&doc["key_codes"], ex);
        if !fails.is_empty() {
            failures.push(format!(
                "{}:\n  {}",
                ex["id"].as_str().unwrap(),
                fails.join("\n  ")
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{}/{} examples failed:\n{}",
        failures.len(),
        examples.len(),
        failures.join("\n")
    );
}

/// Recompute every asserted step's `expect` block from the host core and
/// write the merged document to `$RANDOM_ORACLE_OUT`.
#[test]
#[ignore = "oracle maintenance: writes the merged corpus; set RANDOM_ORACLE_OUT"]
fn dump_random_oracle() {
    let mut doc = load_doc();
    let codes = doc["key_codes"].clone();
    let out = std::env::var_os("RANDOM_ORACLE_OUT").expect("set RANDOM_ORACLE_OUT");
    let examples = doc["examples"].as_array_mut().unwrap();
    for ex in examples.iter_mut() {
        let runs = run_example(&codes, ex);
        let steps = ex["steps"].as_array_mut().unwrap();
        assert_eq!(steps.len(), runs.len(), "{} step count", ex["id"]);
        for (idx, (step, run)) in steps.iter_mut().zip(&runs).enumerate() {
            let obj = step.as_object_mut().unwrap();
            let assert_rows = obj.get("assert_rows").and_then(Value::as_u64).unwrap_or(0) as usize;
            let want_lamps = obj.get("lamps").and_then(Value::as_bool).unwrap_or(false);
            obj.remove("lamps");
            if assert_rows == 0 && !want_lamps {
                continue;
            }
            let mut expect = Map::new();
            if assert_rows > 0 {
                assert!(
                    run.rows.len() >= assert_rows,
                    "{} step {} prints {} rows, {} asserted: {:?}",
                    ex["id"],
                    idx + 1,
                    run.rows.len(),
                    assert_rows,
                    run.rows
                );
                let tape: Vec<Value> = run.rows[run.rows.len() - assert_rows..]
                    .iter()
                    .map(|r| {
                        json!({
                            "value": r.value,
                            "symbol": r.symbol,
                            "red": r.red,
                            "rounded": r.rounded,
                        })
                    })
                    .collect();
                expect.insert("tape".into(), Value::Array(tape));
            }
            if want_lamps {
                expect.insert(
                    "lamps".into(),
                    json!({
                        "memory": run.lamps.memory,
                        "overflow": run.lamps.overflow,
                        "negative": run.lamps.negative,
                    }),
                );
            }
            obj.insert("expect".into(), Value::Object(expect));
        }
    }
    let text = serde_json::to_string_pretty(&doc).unwrap() + "\n";
    std::fs::write(&out, text).unwrap();
    println!("wrote {}", Path::new(&out).display());
}
